import sys
from math import gcd
input_ = lambda : sys.stdin.readline().strip('\r\n')
sys.setrecursionlimit(10 ** 6)
d = {}

def lcm(a, b):
	return a * b // gcd(a, b)

def took(v, w):
	ans = 0
	if w % f[v] == 0:
		return 0
	if d.get(str(v) + 's' + str(w)):
		return d[str(v) + 's' + str(w)]
	if len(g[v]) == 0:
		d[str(v) + 's' + str(w)] = 0
		return 0
	if w % len(g[v]) == 0:
		x = 0
		fact = w // len(g[v])
		for i in g[v]:
			x += took(i, fact)
		d[str(v) + 's' + str(w)] = x
		return x
	d[str(v) + 's' + str(w)] = w
	return w

def dfs(r):
	z = len(g[r])
	if z == 0:
		return 1
	y = 1
	for i in g[r]:
		x = dfs(i)
		f[i] = x
		y = lcm(x, y)
	return y * z

def compress(r):
	a = len(g[r])
	if a == 0:
		return []
	b = []
	for i in g[r]:
		b = compress(i)
	if a > 1:
		return []
	elif b == []:
		return [g[r][0]]
	else:
		g[r][0] = b[0]
		return b
n = int(input_())
a = list(map(int, input_().split()))
g = [[] for i in range(n + 1)]
f = [1 for i in range(n + 1)]
for i in range(n - 1):
	g[a[i]].append(i + 2)
f[1] = dfs(1)
compress(1)
for _ in range(int(input_())):
	(v, w) = list(map(int, input_().split()))
	print(took(v, w))
